/* 当前"层"的结构化上下文：认得出作业 / 100 Days / 视频目录 / 阅读器。
   返回 {kind, ctx}；不在任何层里返回 null（走卡片流）。

   ★ 为什么必须有：作业和 100 Days 是**内嵌面板**（#inlinePanel），它盖在卡片上，
     而 S.cur 还指着底下那张卡。不认层的话，打开作业再问助教，上下文会"回退"到
     底层那张讲义卡（用户报的 bug 原话："作业界面打开之后再打开助教，上下文会自动
     回退到最底层的讲义"）。
   ★ 助教自己开着时（覆盖层），要认它**底下**压着的那一层 —— 他问的是题目，不是助教。

   asContextPoint（定位 chip + 发给模型的 chapter/section/point）与 assistantContext
   （发给模型的正文）共用这一份，免得"显示的说在看作业、发出去的说在看讲义"。 */
function asContextLayer(){
  var kind = "";
  try{ kind = modalKind(); }catch(e){ return null; }
  /* 助教 / OJ 说明这类"盖在面板上的小弹层"：往下看一层 */
  if (kind === "assistant" || kind === "ojconsent" || kind === "ojlogin"){
    kind = surfaceIsInline() ? SURF_KIND : "";
  }
  if (!kind) return null;
  if (kind === "reader") return { kind: kind, ctx: null };   /* 阅读器有专门分支，见 asContextPoint */
  if (kind === "problem" && HW.prob){
    var p = HW.prob, hw = HW.hw || {};
    return { kind: kind, ctx: {
      chapter: "作业",
      section: String(hw.title || hw.id || "作业"),
      point: "第 " + p.no + " 题 " + String(p.title || ""),
      p: null, problem: p
    }};
  }
  if (kind === "hw"){
    var h = HW.hw || {};
    return { kind: kind, ctx: {
      chapter: "作业",
      section: String(h.title || h.id || "作业列表"),
      point: "", p: null
    }};
  }
  if (kind === "days") return { kind: kind, ctx: { chapter: "100 Days", section: "目录", point: "", p: null }};
  if (kind === "videos") return { kind: kind, ctx: { chapter: "视频目录", section: "黑马程序员 Python 全套", point: "", p: null }};
  return { kind: kind, ctx: { chapter: "面板", section: String(kind), point: "", p: null }};
}
